import string

def word_frequency(text: str) -> dict[str, int]:
    translator = str.maketrans('', '', string.punctuation)
    words = text.translate(translator).lower().split()
    freq = {}
    for word in words:
        freq[word] = freq.get(word, 0) + 1
    return freq
